/* ===================== BÀI 28 · Timer 2 trên AT89S52 ===================== */
/* Bài 28 · Timer 2 trên AT89S52 (AMTS-EMB-001-M07-L04, MC51-028) — sinh bởi tools/author/mcu8051/l28.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR28=[{"label":"Ví dụ: Tự nạp 16 bit, TF2 đều mỗi 10 chu kỳ","code":"; Ví dụ 1: Timer 2 tự nạp 16 bit: TF2 bật đều mỗi 10 chu kỳ\n; Chỉ có trên 8052/AT89S52. RCAP2 = 65536 - 10 = FFF6H\n        ORG     0000H\n        MOV     RCAP2H,#0FFH            ; giá trị nạp lại\n        MOV     RCAP2L,#0F6H\n        MOV     TH2,#0FFH               ; lần đếm đầu cũng 10 nhịp\n        MOV     TL2,#0F6H\n        MOV     R7,#3\n        SETB    TR2                     ; T2CON = 04H: tự nạp, bộ định thời\nCHO:    JNB     TF2,CHO\n        CLR     TF2                     ; phần cứng không tự xóa TF2\n        CPL     P1.7                    ; mốc thời gian trên LED P1.7\n        DJNZ    R7,CHO\n        CLR     TR2\n        SJMP    $\n        END\n","note":"SETB TR2 ở chu kỳ 10; TH2:TL2 đếm FFF6H → FFFFH rồi tràn ở chu kỳ 20: phần cứng nạp lại FFF6H, TF2 = 1. TF2 bật lại ở chu kỳ 30 và 40 — đều 10 chu kỳ, dù vòng chờ và CLR TF2, CPL P1.7 tốn thời gian ở giữa. LED P1.7 đổi 3 lần (P1 = 7FH). Cuối: TL2 = FBH (5 nhịp sau lần tràn cuối), T2CON = 00H.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Nạp TH2:TL2 mà quên RCAP2","code":"; Ví dụ 2 (bẫy): nạp TH2:TL2 nhưng quên RCAP2H:RCAP2L\n; Lần đầu 10 nhịp; tràn xong phần cứng nạp RCAP2 = 0000H\n        ORG     0000H\n        MOV     TH2,#0FFH\n        MOV     TL2,#0F6H               ; SAI: chỉ nạp bộ đếm\n        MOV     R7,#2\n        SETB    TR2\nCHO:    JNB     TF2,CHO\n        CLR     TF2\n        CPL     P1.7\n        DJNZ    R7,CHO                  ; lần chờ thứ hai: 65 536 nhịp\n        CLR     TR2\n        SJMP    $\n        END\n","note":"RCAP2 = 0000H (giá trị reset). Lần chờ đầu 10 nhịp như ví dụ 1; lần tràn đó nạp 0000H nên lần chờ thứ hai dài 65 536 nhịp (≈ 65,5 ms ở 12 MHz). Tổng 65 557 chu kỳ. Ví dụ đặt sẵn tốc độ “thời gian thật” để nút Chạy không mất quá lâu; P1.7 đổi hai lần nên P1 = FFH.","dev":{"led":true},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Bắt giữ thời điểm hai sườn ở T2EX","code":"; Ví dụ 3: bắt giữ: chụp TH2:TL2 lúc có sườn xuống ở T2EX\n; Hai lần chụp: 30H:31H và 32H:33H; hiệu = khoảng cách\n        ORG     0000H\n        MOV     T2CON,#09H              ; CP/RL2 = 1 (bắt giữ), EXEN2 = 1\n        SETB    TR2                     ; đếm từ 0000H\n        MOV     R7,#10\n        DJNZ    R7,$                    ; chờ 20 chu kỳ\n        CLR     P1.1                    ; sườn xuống ở T2EX: chụp lần 1\n        SETB    P1.1\n        MOV     30H,RCAP2H\n        MOV     31H,RCAP2L\n        CLR     EXF2\n        MOV     R7,#50\n        DJNZ    R7,$                    ; chờ 100 chu kỳ\n        CLR     P1.1                    ; chụp lần 2\n        SETB    P1.1\n        MOV     32H,RCAP2H\n        MOV     33H,RCAP2L\n        CLR     TR2\n        SJMP    $\n        END\n","note":"T2CON = 09H: bắt giữ, EXEN2 = 1. CLR P1.1 ở chu kỳ 25 tạo sườn; chu kỳ 26 phần cứng chụp 0016H vào RCAP2, EXF2 = 1 (T2CON = 4DH). Lần 2 ở chu kỳ 133 chụp 0082H. Hiệu 0082H − 0016H = 6CH = 108 chu kỳ = khoảng cách giữa hai lệnh CLR P1.1. Bộ đếm không dừng khi chụp (TL2 cuối = 88H).","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Sườn T2EX nạp lại sớm (EXEN2 = 1)","code":"; Ví dụ 4: tự nạp có EXEN2 = 1: sườn ở T2EX nạp lại sớm\n; Dùng để đồng bộ timer với một tín hiệu ngoài\n        ORG     0000H\n        MOV     RCAP2H,#0FFH\n        MOV     RCAP2L,#00H             ; nạp lại FF00H (256 nhịp)\n        MOV     TH2,#0FFH\n        MOV     TL2,#00H\n        MOV     T2CON,#08H              ; tự nạp, EXEN2 = 1\n        SETB    TR2\n        MOV     R7,#20\n        DJNZ    R7,$                    ; chờ 40 chu kỳ\n        MOV     30H,TL2                 ; số đếm trước sườn\n        CLR     P1.1                    ; sườn ở T2EX: nạp lại FF00H\n        SETB    P1.1\n        MOV     31H,TL2                 ; số đếm sau sườn\n        CLR     TR2\n        SJMP    $\n        END\n","note":"Tự nạp với RCAP2 = FF00H, EXEN2 = 1. Sau vòng chờ, 30H = TL2 = 2AH. Sườn ở T2EX (CLR P1.1, chu kỳ 55) làm phần cứng nạp lại FF00H ở chu kỳ 56 dù chưa tràn, EXF2 = 1; 31H = 02H. TF2 không bật vì không có tràn.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Timer 2 đếm sự kiện ở chân T2 (P1.0)","code":"; Ví dụ 5: Timer 2 đếm sự kiện ở chân T2 (P1.0), C/T2 = 1\n; Chương trình tự tạo 5 sườn xuống ở P1.0\n        ORG     0000H\n        MOV     T2CON,#02H              ; C/T2 = 1, tự nạp (RCAP2 = 0)\n        SETB    TR2\n        MOV     R7,#5\nXUNG:   CLR     P1.0                    ; sườn xuống ở T2\n        NOP\n        SETB    P1.0\n        DJNZ    R7,XUNG\n        CLR     TR2                     ; TL2 = 05H\n        SJMP    $\n        END\n","note":"T2CON = 02H: C/T2 = 1, Timer 2 đếm sườn xuống ở chân T2 (P1.0), không đếm chu kỳ máy. Mỗi vòng tạo một sườn; TL2 tăng 2 chu kỳ sau CLR P1.0 như Bài 27. Cuối: TL2 = 05H. ucsim s51 không mô phỏng C/T2 (nó cho TL2 = 1BH, tức đếm chu kỳ máy): ví dụ này chỉ kiểm bằng tính tay.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Xuất xung 250 kHz ở P1.0 (T2OE)","code":"; Ví dụ 6: xuất xung ở P1.0 (T2OE = 1 trong T2MOD)\n; f = 12 MHz / (4 x (65536 - FFF4H)) = 12 MHz / 48 = 250 kHz\n        ORG     0000H\n        MOV     T2MOD,#02H              ; T2OE = 1 (không định địa chỉ bit)\n        MOV     RCAP2H,#0FFH\n        MOV     RCAP2L,#0F4H            ; 12 lần đếm mỗi nửa chu kỳ\n        MOV     TH2,#0FFH\n        MOV     TL2,#0F4H\n        SETB    TR2                     ; C/T2 = 0: P1.0 đảo mỗi 2 chu kỳ\n        MOV     R7,#10\n        DJNZ    R7,$                    ; xem P1.0 trên đồ thị thời gian\n        CLR     TR2\n        SJMP    $\n        END\n","note":"T2MOD = 02H (T2OE = 1), RCAP2 = FFF4H: mỗi lần tràn cách 12 nhịp f_osc/2 = 2 chu kỳ máy, P1.0 đảo, nên chu kỳ xung 4 chu kỳ máy → 250 kHz ở 12 MHz. Xem P1.0 trên phần Thời gian (chốt P1 vẫn FFH). TF2 không bật ở chế độ này. ucsim s51 không có T2MOD: chỉ kiểm bằng tính tay.","dev":{"led":true},"fosc":12000000}];
const sim28=makeSim51(document.getElementById("m51-l28"),{id:"s28",presets:PR28,ram:256});
makeEx51(document.getElementById("ex-l28"),"l28",[{"t":"Cấu hình Timer 2 tự nạp 16 bit","d":"<p>Ô <code>30H<\/code> (byte cao), <code>31H<\/code> (byte thấp) chứa N (16 ≤ N ≤ 65 535). Hãy cấu hình <b>Timer 2 của AT89S52<\/b> ở chế độ tự nạp 16 bit, bộ định thời (C/T2 = 0), không làm nguồn baud, xóa mọi cờ cũ, sao cho TF2 bật đều mỗi N chu kỳ máy <b>kể từ lần đầu<\/b>: nạp RCAP2H:RCAP2L và TH2:TL2, rồi cho chạy: <code>SETB TR2<\/code> là lệnh ngay trước <code>SJMP $<\/code>. Khi dừng ở <code>SJMP $<\/code>: T2CON = 04H; trang kiểm cả TL2 (timer đã đếm 2 nhịp của <code>SJMP $<\/code>, nên TL2 = byte thấp của giá trị nạp + 2). Các bộ thử đặt sẵn T2CON với cấu hình cũ khác nhau.<\/p><p>Ví dụ: N = 1000 → RCAP2H = TH2 = FCH, RCAP2L = 18H (TL2 bắt đầu 18H, khi dừng TL2 = 1AH).<\/p>","start":"        ORG     0000H\n        MOV     TH2,30H                 ; nạp N?\n        MOV     TL2,31H\n        SETB    TR2\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":232},"regs":{"T2CON":0,"RCAP2H":85,"RCAP2L":85,"TH2":85,"TL2":85}},"expect":{"iram":{"0x30":3,"0x31":232},"regs":{"RCAP2H":252,"RCAP2L":24,"TH2":252,"TL2":26,"T2CON":4}}},{"setup":{"iram":{"0x30":195,"0x31":80},"regs":{"T2CON":48,"RCAP2H":85,"RCAP2L":85,"TH2":85,"TL2":85,"PSW":128}},"expect":{"iram":{"0x30":195,"0x31":80},"regs":{"RCAP2H":60,"RCAP2L":176,"TH2":60,"TL2":178,"T2CON":4}}},{"setup":{"iram":{"0x30":0,"0x31":16},"regs":{"T2CON":0,"RCAP2H":85,"RCAP2L":85,"TH2":85,"TL2":85}},"expect":{"iram":{"0x30":0,"0x31":16},"regs":{"RCAP2H":255,"RCAP2L":240,"TH2":255,"TL2":242,"T2CON":4}}},{"setup":{"iram":{"0x30":255,"0x31":255},"regs":{"T2CON":1,"RCAP2H":85,"RCAP2L":85,"TH2":85,"TL2":85}},"expect":{"iram":{"0x30":255,"0x31":255},"regs":{"RCAP2H":0,"RCAP2L":1,"TH2":0,"TL2":3,"T2CON":4}}},{"setup":{"iram":{"0x30":1,"0x31":0},"regs":{"T2CON":192,"RCAP2H":85,"RCAP2L":85,"TH2":85,"TL2":85}},"expect":{"iram":{"0x30":1,"0x31":0},"regs":{"RCAP2H":255,"RCAP2L":0,"TH2":255,"TL2":2,"T2CON":4}}},{"setup":{"iram":{"0x30":3,"0x31":154},"regs":{"T2CON":2,"RCAP2H":85,"RCAP2L":85,"TH2":85,"TL2":85}},"expect":{"iram":{"0x30":3,"0x31":154},"regs":{"RCAP2H":252,"RCAP2L":102,"TH2":252,"TL2":104,"T2CON":4}}},{"setup":{"iram":{"0x30":78,"0x31":32},"regs":{"T2CON":8,"RCAP2H":85,"RCAP2L":85,"TH2":85,"TL2":85}},"expect":{"iram":{"0x30":78,"0x31":32},"regs":{"RCAP2H":177,"RCAP2L":224,"TH2":177,"TL2":226,"T2CON":4}}}]},"hints":["Giá trị nạp như Bài 26: 65536 − N = 0 − N, trừ hai byte có mượn. Ghi vào cả RCAP2 (để nạp lại) và TH2:TL2 (lần đầu).","T2CON định địa chỉ bit nhưng có 8 bit cần đúng: ghi cả byte MOV T2CON,#00H trước rồi SETB TR2 sau cùng (hoặc MOV T2CON,#04H khi đã nạp xong)."],"why":"Timer 2 tự nạp 16 bit thay cho Timer 0 chế độ 1 + nạp lại phần mềm: không có overhead (ví dụ 1). Quên RCAP2 thì từ lần thứ hai chu kỳ thành 65 536 (ví dụ 2); quên TH2:TL2 thì lần đầu sai. Bộ thử có RCLK/TCLK, CP/RL2, C/T2, EXEN2, TF2, EXF2 cũ: chỉ SETB TR2 là không đủ."},{"t":"Chu kỳ từ hai lần bắt giữ","d":"<p>Timer 2 ở chế độ bắt giữ đếm chu kỳ máy. Lần chụp thứ nhất ở <code>30H<\/code>:<code>31H<\/code>, lần thứ hai ở <code>32H<\/code>:<code>33H<\/code> (byte cao trước). Ô <code>34H<\/code> là số lần TF2 bật (tràn) giữa hai lần chụp. Hãy tính khoảng cách 24 bit = 34H × 65 536 + (lần 2) − (lần 1) vào <code>35H<\/code> (cao), <code>36H<\/code>, <code>37H<\/code> (thấp). Đề bảo đảm kết quả không âm.<\/p><p>Ví dụ (số liệu của ví dụ 3): lần 1 = 0016H, lần 2 = 0082H, không tràn → 00006CH = 108 chu kỳ.<\/p>","start":"        ORG     0000H\n        CLR     C\n        MOV     A,33H\n        SUBB    A,31H                   ; byte thấp: lần 2 - lần 1\n        MOV     37H,A\n        MOV     A,32H\n        SUBB    A,30H                   ; byte cao\n        MOV     36H,A\n        MOV     35H,34H                 ; số lần tràn (chưa trừ mượn)\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":22,"0x32":0,"0x33":130,"0x34":0,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x35":0,"0x36":0,"0x37":108}}},{"setup":{"iram":{"0x30":240,"0x31":0,"0x32":16,"0x33":0,"0x34":1,"0x35":238,"0x36":238,"0x37":238},"regs":{"PSW":128}},"expect":{"iram":{"0x35":0,"0x36":32,"0x37":0}}},{"setup":{"iram":{"0x30":18,"0x31":52,"0x32":86,"0x33":120,"0x34":1,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x35":1,"0x36":68,"0x37":68}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":1,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x35":1,"0x36":0,"0x37":0}}},{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":255,"0x33":255,"0x34":0,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x35":0,"0x36":255,"0x37":254}}},{"setup":{"iram":{"0x30":128,"0x31":0,"0x32":127,"0x33":255,"0x34":3,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x35":2,"0x36":255,"0x37":255}}},{"setup":{"iram":{"0x30":0,"0x31":255,"0x32":1,"0x33":0,"0x34":0,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x35":0,"0x36":0,"0x37":1}}},{"setup":{"iram":{"0x30":171,"0x31":205,"0x32":171,"0x33":205,"0x34":255,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x35":255,"0x36":0,"0x37":0}}}]},"hints":["Đây là phép trừ 24 bit: (34H : lần 2) − (00H : lần 1). Bắt đầu CLR C, SUBB từ byte thấp lên.","Byte cao nhất: lấy 34H trừ 0 và trừ mượn từ phép trừ 16 bit (SUBB A,#0)."],"why":"Ở chế độ bắt giữ timer chạy liên tục, mỗi lần tràn TH2:TL2 về 0000H. Khi lần 2 nhỏ hơn lần 1 (test 2), phép trừ 16 bit mượn 1 từ số lần tràn. Code mẫu quên mượn này nên sai khi lần 2 nhỏ hơn lần 1 (test 2, 6)."},{"t":"Timer 2 làm nguồn baud, code ngắn","d":"<p>Thạch anh 11,0592 MHz. Ô <code>30H<\/code> chứa k (0…5); tốc độ cần = 1200 × 2<sup>k<\/sup> baud (1200, 2400, 4800, 9600, 19 200, 38 400). Hãy dùng <b>Timer 2 làm nguồn baud<\/b> cho cả phát và nhận (Timer 1 đang dùng việc khác: TMOD, TCON giữ nguyên): RCAP2H:RCAP2L = 65536 − f<sub>osc<\/sub> / (32 × baud), T2CON = 34H (RCLK = TCLK = 1, TR2 = 1), SCON = 50H (UART chế độ 1, cho phép nhận — học ở Chương 9). Giới hạn: <b>≤ 30 byte<\/b>, ≤ 60 chu kỳ máy.<\/p><p>Ví dụ: k = 3 (9600 baud) → 11 059 200 / (32 × 9600) = 36, RCAP2 = FFDCH.<\/p>","start":"        ORG     0000H\n        MOV     TMOD,#20H               ; cách cũ: Timer 1 chế độ 2 làm nguồn\n                                        ; baud\n        MOV     TH1,#0FDH               ; 9600 baud ở 11,0592 MHz (SMOD = 0)\n        MOV     TL1,#0FDH\n        SETB    TR1\n        MOV     SCON,#50H               ; UART chế độ 1, cho phép nhận\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3},"regs":{"TMOD":33,"TCON":64,"T2CON":0,"SCON":0}},"expect":{"regs":{"RCAP2H":255,"RCAP2L":220,"T2CON":52,"SCON":80,"TMOD":33,"TCON":64}}},{"setup":{"iram":{"0x30":0},"regs":{"TMOD":1,"TCON":16,"T2CON":0,"SCON":0}},"expect":{"regs":{"RCAP2H":254,"RCAP2L":224,"T2CON":52,"SCON":80,"TMOD":1,"TCON":16}}},{"setup":{"iram":{"0x30":1},"regs":{"TMOD":0,"TCON":0,"T2CON":0,"SCON":0}},"expect":{"regs":{"RCAP2H":255,"RCAP2L":112,"T2CON":52,"SCON":80,"TMOD":0,"TCON":0}}},{"setup":{"iram":{"0x30":2},"regs":{"TMOD":32,"TCON":64,"T2CON":0,"SCON":0}},"expect":{"regs":{"RCAP2H":255,"RCAP2L":184,"T2CON":52,"SCON":80,"TMOD":32,"TCON":64}}},{"setup":{"iram":{"0x30":4},"regs":{"TMOD":17,"TCON":80,"T2CON":0,"SCON":0}},"expect":{"regs":{"RCAP2H":255,"RCAP2L":238,"T2CON":52,"SCON":80,"TMOD":17,"TCON":80}}},{"setup":{"iram":{"0x30":5},"regs":{"TMOD":2,"TCON":16,"T2CON":0,"SCON":0}},"expect":{"regs":{"RCAP2H":255,"RCAP2L":247,"T2CON":52,"SCON":80,"TMOD":2,"TCON":16}}}],"maxCyc":60,"maxBytes":30},"hints":["f_osc / (32 × 1200 × 2^k) = 288 / 2^k: 288, 144, 72, 36, 18, 9 — luôn chia hết.","Có thể dịch phải 288 k lần (16 bit) rồi lấy số đối; hoặc dịch phải số học thẳng −288 = FEE0H (bit dấu bằng 1 đưa vào từ trái) — đỡ phép lấy số đối.","Code mẫu là cách cũ với Timer 1 (TMOD = 20H, TH1 = FDH): đúng 9600 baud nhưng làm hỏng Timer 1 và không dùng Timer 2."],"why":"Timer 2 cho baud = f_osc / (32 × (65536 − RCAP2)) với 16 bit nạp lại, giải phóng Timer 1. Lời giải tham chiếu: −288 = FEE0H, dịch phải số học k lần (XCH, SETB C, RRC, XCH, RRC), 28 byte, tối đa 53 chu kỳ tính cả SJMP $ (k = 5)."}]);

makeQuiz("quiz28","score28",[{"q": "Cần TF2 bật đều mỗi 50 000 chu kỳ máy bằng Timer 2 tự nạp. Nạp RCAP2H:RCAP2L bằng bao nhiêu?", "o": ["C350H", "3CB0H", "B03CH", "FFFFH − C350H = 3CAFH"], "a": 1, "e": "65 536 − 50 000 = 15 536 = 3CB0H. C350H là chính 50 000; 3CAFH thiếu 1 vì phép tính đúng là 10000H − N, không phải FFFFH − N."}, {"q": "Timer 2 tự nạp, cần TF2 bật mỗi 1 000 nhịp (giá trị nạp FC18H), nhưng chương trình chỉ nạp TH2:TL2 = FC18H và quên RCAP2 (sau reset RCAP2 = 0000H). Các lần TF2 bật cách nhau bao nhiêu?", "o": ["Lần đầu 1 000 nhịp, các lần sau 65 536 nhịp", "Luôn 1 000 nhịp", "Luôn 65 536 nhịp", "TF2 không bao giờ bật"], "a": 0, "e": "Lần đầu đếm từ giá trị đã nạp vào TH2:TL2; mỗi lần tràn phần cứng chép RCAP2 = 0000H vào nên từ lần sau đủ 65 536 nhịp (ví dụ 2)."}, {"q": "Ở chế độ bắt giữ (CP/RL2 = 1, EXEN2 = 1), khi có sườn xuống ở T2EX thì điều gì xảy ra?", "o": ["TH2:TL2 về 0000H và TF2 = 1", "RCAP2 được chép vào TH2:TL2", "Timer 2 dừng cho tới khi phần mềm đặt lại TR2", "TH2:TL2 được chép vào RCAP2H:RCAP2L, EXF2 = 1, bộ đếm chạy tiếp"], "a": 3, "e": "Bắt giữ chụp giá trị bộ đếm vào RCAP2 và báo bằng EXF2; bộ đếm không dừng (ví dụ 3). Chép RCAP2 vào TH2:TL2 là tự nạp (ví dụ 4)."}, {"q": "Thạch anh 11,0592 MHz, Timer 2 làm nguồn baud 19 200. RCAP2 bằng bao nhiêu?", "o": ["FFDCH", "FFFDH", "FFEEH", "FFB8H"], "a": 2, "e": "11 059 200 / (32 × 19 200) = 18; 65 536 − 18 = 65 518 = FFEEH. FFDCH là 9600 baud, FFB8H là 4800 baud; FDH là giá trị TH1 của Timer 1 cho 9600 baud."}, {"q": "Một chương trình dùng Timer 2 chạy tốt trên AT89S52 nhưng treo ở JNB TF2,$ khi nạp vào 8051 gốc (hoặc AT89S51). Vì sao?", "o": ["8051 gốc chỉ có Timer 2 ở chế độ bắt giữ", "8051 gốc không có Timer 2: không có T2CON thật, TF2 không bao giờ bật", "Cần ghi T2MOD trước trên 8051", "Thạch anh của 8051 gốc chậm hơn"], "a": 1, "e": "Timer 2 là phần mở rộng của dòng 8052. Trên 8051 gốc địa chỉ C8H… không có thanh ghi, vòng chờ không bao giờ thoát."}]);

